    20→package ids.messaging.endpoint;
    21→
    22→import javax.servlet.ServletException;
    23→import javax.servlet.http.HttpServletRequest;
    24→import java.io.ByteArrayInputStream;
    25→import java.io.IOException;
    26→import java.net.URI;
    27→import java.nio.charset.StandardCharsets;
    28→import java.util.List;
    29→import java.util.Map;
    30→import java.util.Optional;
    31→import java.util.Scanner;
    32→
    33→import com.fasterxml.jackson.databind.ObjectMapper;
    34→import de.fraunhofer.iais.eis.DynamicAttributeTokenBuilder;
    35→import de.fraunhofer.iais.eis.Message;
    36→import de.fraunhofer.iais.eis.RejectionMessageBuilder;
    37→import de.fraunhofer.iais.eis.RejectionReason;
    38→import de.fraunhofer.iais.eis.TokenFormat;
    39→import de.fraunhofer.iais.eis.ids.jsonld.Serializer;
    40→import ids.messaging.common.SerializeException;
    41→import ids.messaging.core.config.ConfigContainer;
    42→import ids.messaging.dispatcher.MessageDispatcher;
    43→import ids.messaging.dispatcher.filter.PreDispatchingFilterException;
    44→import ids.messaging.protocol.multipart.parser.MultipartDatapart;
    45→import ids.messaging.util.IdsMessageUtils;
    46→import lombok.extern.slf4j.Slf4j;
    47→import org.apache.commons.io.IOUtils;
    48→import org.springframework.beans.factory.annotation.Autowired;
    49→import org.springframework.beans.factory.annotation.Value;
    50→import org.springframework.http.HttpStatus;
    51→import org.springframework.http.MediaType;
    52→import org.springframework.http.ResponseEntity;
    53→import org.springframework.stereotype.Controller;
    54→import org.springframework.util.LinkedMultiValueMap;
    55→import org.springframework.util.MultiValueMap;
    56→
    57→/**
    58→ * REST controller for handling all incoming IDS multipart Messages.
    59→ */
    60→@Slf4j
    61→@Controller
    62→public class MessageController {
    63→
    64→    /**
    65→     * The MessageDispatcher.
    66→     */
    67→    private final MessageDispatcher messageDispatcher;
    68→
    69→    /**
    70→     * The ConfigContainer.
    71→     */
    72→    private final ConfigContainer configContainer;
    73→
    74→    /**
    75→     * The infomodel serializer.
    76→     */
    77→    private final Serializer serializer;
    78→
    79→    /**
    80→     * Used to switch incoming infomodel version compatibility check off or on (default on).
    81→     */
    82→    @Value("#{new Boolean('${infomodel.compatibility.validation:true}')}")
    83→    private Boolean validateInfVer;
    84→
    85→    /**
    86→     * Used to switch logging incoming requests off or on (default off).
    87→     */
    88→    @Value("#{new Boolean('${messaging.log.incoming:false}')}")
    89→    private Boolean logIncoming;
    90→
    91→    /**
    92→     * Used to switch logging send responses to incoming requests off or on (default off).
    93→     */
    94→    @Value("#{new Boolean('${messaging.log.outgoing:false}')}")
    95→    private Boolean logResponse;
    96→
    97→    /**
    98→     * Constructor for the MessageController.
    99→     * @param messageDispatcher The MessageDispatcher.
   100→     * @param serializer The infomodel serializer.
   101→     * @param configContainer The ConfigContainer.
   102→     */
   103→    @Autowired
   104→    public MessageController(final MessageDispatcher messageDispatcher,
   105→                             final Serializer serializer,
   106→                             final ConfigContainer configContainer) {
   107→        this.messageDispatcher = messageDispatcher;
   108→        this.serializer = serializer;
   109→        this.configContainer = configContainer;
   110→    }
   111→
   112→    /**
   113→     * Generic method to handle all incoming ids messages. One Method to Rule them All.
   114→     * Get header and payload from incoming message, let the MessageDispatcher and
   115→     * MessageHandler process it and return the result as a Multipart response.
   116→     *
   117→     * @param request Incoming http request.
   118→     * @return Multipart MultivalueMap containing ResponseMessage header and some payload.
   119→     */
   120→    public ResponseEntity<MultiValueMap<String, Object>> handleIDSMessage(
   121→            final HttpServletRequest request) {
   122→        try {
   123→            if (log.isInfoEnabled()) {
   124→                log.info("Received incoming message. [code=(IMSMEI0059)]");
   125→            }
   126→
   127→            final var headerPart =
   128→                    request.getPart(MultipartDatapart.HEADER.toString());
   129→            final var payloadPart =
   130→                    request.getPart(MultipartDatapart.PAYLOAD.toString());
   131→
   132→            if (headerPart == null) {
   133→                if (log.isDebugEnabled()) {
   134→                    log.debug("Header of incoming message were empty! [code=(IMSMED0119)]");
   135→                }
   136→
   137→                return ResponseEntity.status(HttpStatus.BAD_REQUEST)
   138→                                     .body(createDefaultErrorMessage(
   139→                                             RejectionReason.MALFORMED_MESSAGE,
   140→                                             "Header was missing!"));
   141→            }
   142→
   143→            final var headerBytes = IOUtils.toByteArray(headerPart.getInputStream());
   144→            logIncomingMessage(headerBytes);
   145→            String input;
   146→
   147→            if (log.isDebugEnabled()) {
   148→                log.debug("Parsing header of incoming message. [code=(IMSMED0120)]");
   149→            }
   150→
   151→            final var headerInput = new ByteArrayInputStream(headerBytes);
   152→
   153→            try (var scanner = new Scanner(headerInput,
   154→                                           StandardCharsets.UTF_8.name())) {
   155→                input = scanner.useDelimiter("\\A").next();
   156→            }
   157→
   158→            headerInput.close();
   159→
   160→            final var infomodelCompability = validateInfomodelVersion(input);
   161→
   162→            if (infomodelCompability.isPresent()) {
   163→                final var errorMessage = infomodelCompability.get();
   164→
   165→                if (log.isWarnEnabled()) {
   166→                    log.warn("Infomodel model version validation of received messages is switched"
   167→                             + " on. Model-version of incoming message not supported."
   168→                             + " Sending BAD_REQUEST response as a result."
   169→                             + " [code=(IMSMEW0042), response-message=({})]",
   170→                             errorMessage);
   171→                }
   172→
   173→                return ResponseEntity
   174→                        .status(HttpStatus.BAD_REQUEST)
   175→                        .body(createDefaultErrorMessage(
   176→                                RejectionReason.VERSION_NOT_SUPPORTED,
   177→                                errorMessage));
   178→            }
   179→
   180→            // Deserialize JSON-LD headerPart to its RequestMessage.class
   181→            final var requestHeader = serializer.deserialize(input, Message.class);
   182→
   183→            if (log.isDebugEnabled()) {
   184→                log.debug("Hand the incoming message to the message dispatcher!"
   185→                          + " [code=(IMSMED0121)]");
   186→            }
   187→
   188→            //pass null if payloadPart is null, else pass it as inputStream
   189→            final var response = this.messageDispatcher
   190→                    .process(requestHeader, payloadPart == null
   191→                            ? null
   192→                            : payloadPart.getInputStream());
   193→
   194→            if (response != null) {
   195→                //get Response as MultiValueMap
   196→                final var responseAsMap = createMultiValueMap(
   197→                        response.createMultipartMap(serializer));
   198→
   199→                // return the ResponseEntity as Multipart content
   200→                // with created MultiValueMap
   201→                if (log.isInfoEnabled()) {
   202→                    log.info("Sending response with status OK (200). [code=(IMSMEI0061)]");
   203→                }
   204→
   205→                logResponseHeader(responseAsMap);
   206→
   207→                return ResponseEntity
   208→                        .status(HttpStatus.OK)
   209→                        .contentType(MediaType.MULTIPART_FORM_DATA)
   210→                        .body(responseAsMap);
   211→            } else {
   212→                //if no response-body specified by the implemented handler
   213→                // of the connector (e.g. for received RequestInProcessMessage)
   214→
   215→                if (log.isDebugEnabled()) {
   216→                    log.debug("Implemented Message-Handler didn't return a response,"
   217→                              + " sending status OK instead as response! [code=(IMSMED0122)]");
   218→                }
   219→
   220→                if (log.isInfoEnabled()) {
   221→                    log.info("Sending response with status OK (200) without body."
   222→                            + " [code=(IMSMEI0062)]");
   223→                }
   224→
   225→                return ResponseEntity
   226→                        .status(HttpStatus.OK)
   227→                        .build();
   228→            }
   229→        } catch (PreDispatchingFilterException e) {
   230→            if (log.isErrorEnabled()) {
   231→                log.error("Error during pre-processing with a PreDispatchingFilter!"
   232→                          + " Sending BAD_REQUEST as response."
   233→                          + " [code=(IMSMEE0021), exception=({})]", e.getMessage());
   234→            }
   235→            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
   236→                                 .body(createDefaultErrorMessage(
   237→                                     RejectionReason.BAD_PARAMETERS,
   238→                                     String.format(
   239→                                         "Error during preprocessing: %s", e.getMessage())));
   240→        } catch (IOException | SerializeException e) {
   241→            if (log.isWarnEnabled()) {
   242→                log.warn("Incoming message could not be parsed, sending response BAD_REQUEST"
   243→                         + " with RejectionReason.MALFORMED_MESSAGE! [code=(IMSMEW0043),"
   244→                         + " exception=({})]", e.getMessage());
   245→            }
   246→
   247→            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
   248→                                 .body(createDefaultErrorMessage(
   249→                                         RejectionReason.MALFORMED_MESSAGE,
   250→                                         "Could not parse incoming message!"));
   251→        } catch (ServletException e) {
   252→            if (log.isWarnEnabled()) {
   253→                log.warn("Incoming request was not multipart!"
   254→                         + " Sending INTERNAL_SERVER_ERROR as response [code=(IMSMEW0044),"
   255→                         + " exception=({})]", e.getMessage());
   256→            }
   257→
   258→            return ResponseEntity
   259→                         .status(HttpStatus.INTERNAL_SERVER_ERROR)
   260→                         .body(createDefaultErrorMessage(
   261→                             RejectionReason.INTERNAL_RECIPIENT_ERROR,
   262→                             String.format(
   263→                                 "Could not read incoming request! Error: %s", e.getMessage())));
   264→        }
   265→    }
   266→
   267→    private void logIncomingMessage(final byte[] headerBytes) throws IOException {
   268→        if (Boolean.TRUE.equals(logIncoming)) {
   269→            final var headerInput = new ByteArrayInputStream(headerBytes);
   270→            log.info("Incoming message header: {} [code=(IMSMEI0060)]",
   271→                    IOUtils.toString(headerInput, StandardCharsets.UTF_8));
   272→            headerInput.close();
   273→        }
   274→    }
   275→
   276→    private void logResponseHeader(final MultiValueMap<String, Object> responseAsMap) {
   277→        if (Boolean.TRUE.equals(logResponse)) {
   278→            final var header = responseAsMap.get(MultipartDatapart.HEADER.toString()).toString();
   279→            log.info("Send response header: {} [code=(IMSMEI0063)]", header);
   280→        }
   281→    }
   282→
   283→    /**
   284→     * Decides whether to run the infomodel compatibility check and if so, whether the
   285→     * incoming message is compatible.
   286→     *
   287→     * @param input The received message.
   288→     * @return Optional<String> Empty if successful or skipped, else error message as string.
   289→     * @throws IOException No model version information found in the header.
   290→     */
   291→    private Optional<String> validateInfomodelVersion(final String input) throws IOException {
   292→        if (validateInfVer) {
   293→            return checkInboundVersion(input);
   294→        } else {
   295→            if (log.isDebugEnabled()) {
   296→                log.debug("Skipped validating infomodel compability! [code=(IMSMED0123)]");
   297→            }
   298→            return Optional.empty();
   299→        }
   300→    }
   301→
   302→    /**
   303→     * Create a Spring {@link MultiValueMap} from a {@link java.util.Map}.
   304→     *
   305→     * @param map A map as provided by the MessageResponse.
   306→     * @return A MultiValueMap used as ResponseEntity for Spring.
   307→     */
   308→    private MultiValueMap<String, Object> createMultiValueMap(
   309→            final Map<String, Object> map) {
   310→        if (log.isDebugEnabled()) {
   311→            log.debug("Creating MultiValueMap for the response... [code=(IMSMED0124)]");
   312→        }
   313→
   314→        final var multiMap = new LinkedMultiValueMap<String, Object>();
   315→
   316→        for (final var entry : map.entrySet()) {
   317→            multiMap.put(entry.getKey(), List.of(entry.getValue()));
   318→        }
   319→
   320→        return multiMap;
   321→    }
   322→
   323→    /**
   324→     * Create a default RejectionMessage with a given RejectionReason
   325→     * and specific error message for the payload.
   326→     *
   327→     * @param rejectionReason Reason why the message was rejected.
   328→     * @param errorMessage A specific error message for the payload.
   329→     * @return MultiValueMap with given error information that can
   330→     * be used for a multipart response.
   331→     */
   332→    private MultiValueMap<String, Object> createDefaultErrorMessage(
   333→            final RejectionReason rejectionReason,
   334→            final String errorMessage) {
   335→        try {
   336→            final var rejectionMessage = new RejectionMessageBuilder()
   337→                    ._securityToken_(
   338→                            new DynamicAttributeTokenBuilder()
   339→                                    ._tokenFormat_(TokenFormat.JWT)
   340→                                    ._tokenValue_("rejected!")
   341→                                    .build())
   342→                    ._correlationMessage_(URI.create("https://INVALID"))
   343→                    ._senderAgent_(configContainer.getConnector().getId())
   344→                    ._modelVersion_(configContainer.getConnector()
   345→                                                   .getOutboundModelVersion())
   346→                    ._rejectionReason_(rejectionReason)
   347→                    ._issuerConnector_(configContainer.getConnector().getId())
   348→                    ._issued_(IdsMessageUtils.getGregorianNow())
   349→                    .build();
   350→
   351→            final var multiMap = new LinkedMultiValueMap<String, Object>();
   352→            multiMap.put(MultipartDatapart.HEADER.toString(),
   353→                         List.of(serializer.serialize(rejectionMessage)));
   354→            multiMap.put(MultipartDatapart.PAYLOAD.toString(),
   355→                         List.of(errorMessage));
   356→
   357→            return multiMap;
   358→        } catch (IOException e) {
   359→            if (log.isErrorEnabled()) {
   360→                log.error("Serializer threw exception while creating default rejection message!"
   361→                          + " [code=(IMSMEE0022), exception=({})]", e.getMessage());
   362→            }
   363→            return null;
   364→        }
   365→    }
   366→
   367→    /**
   368→     * @param input Controllers header input as string.
   369→     * @return Optional<String> Empty if successful, else error message as string payload.
   370→     * @throws IOException If no infomodel version is found in input.
   371→     */
   372→    private Optional<String> checkInboundVersion(final String input) throws IOException {
   373→        final var jsonInput = new ObjectMapper().readTree(input);
   374→
   375→        if (jsonInput.has("ids:modelVersion")) {
   376→            final var inputVersion = jsonInput.get("ids:modelVersion")
   377→                                              .textValue();
   378→            final var inboundList = configContainer.getConfigurationModel()
   379→                    .getConnectorDescription()
   380→                    .getInboundModelVersion();
   381→
   382→            final var compatible = inboundList.stream()
   383→                                              .map(supportedVersion -> checkInfomodelContainment(
   384→                                                      inputVersion, supportedVersion))
   385→                                              .reduce(Boolean::logicalOr)
   386→                                              .orElse(false);
   387→
   388→            if (!compatible) {
   389→                final var message = "Infomodel version of incoming Message not in"
   390→                                    + " supported inbound model version list!"
   391→                                    + " [incoming=(" + inputVersion + "),"
   392→                                    + " supported=(" + inboundList + ")]";
   393→                return Optional.of(message);
   394→            }
   395→
   396→            return Optional.empty();
   397→        } else {
   398→            throw new IOException("No ModelVersion in incoming header!");
   399→        }
   400→    }
   401→
   402→    /**
   403→     * @param input Input infomodel version (eg 4.0.1).
   404→     * @param accepted Accepted infomodel version (eg 4.0.2, supports wildcards eg 4.*.*).
   405→     * @return True if infomodel input is covered by accepted input.
   406→     */
   407→    private boolean checkInfomodelContainment(final String input,
   408→                                              final String accepted) {
   409→        if (input.equals(accepted))  {
   410→            return true;
   411→        }
   412→
   413→        final var acceptedSplit = accepted.split("\\.");
   414→        final var inputSplit = input.split("\\.");
   415→
   416→        if (inputSplit.length != acceptedSplit.length) {
   417→            return false;
   418→        }
   419→
   420→        for (var i = 0; i < inputSplit.length; i++) {
   421→           if (!inputSplit[i].equals(acceptedSplit[i])
   422→               && !"*".equals(acceptedSplit[i])) {
   423→               return false;
   424→           }
   425→        }
   426→        return true;
   427→    }
   428→}
   429→

