    92→     * @return An {@link okhttp3.OkHttpClient.Builder} using
    93→     * the current configuration of the connector.
    94→     * @throws NoSuchAlgorithmException If the cryptographic is unknown.
    95→     * @throws KeyManagementException If there is an error with any configured key.
    96→     */
    97→    private static OkHttpClient.Builder createClientBuilder(final ConfigurationModel connector,
    98→                                                            final KeyStoreManager manager)
    99→            throws NoSuchAlgorithmException, KeyManagementException {
   100→
   101→        final var okHttpBuilder = getOkHttpBuilder();
   102→
   103→        if (connector.getConnectorDeployMode() == ConnectorDeployMode.PRODUCTIVE_DEPLOYMENT) {
   104→            if (log.isDebugEnabled()) {
   105→                log.debug("Productive Deployment, use Trustmanager from KeyStoreManager."
   106→                          + " [code=(IMSMED0066)]");
   107→            }
