   109→            setSSLSocketFactory(manager, okHttpBuilder);
   110→        } else if (connector.getConnectorDeployMode() == ConnectorDeployMode.TEST_DEPLOYMENT) {
   111→            setAcceptingAllSSLCertificates(okHttpBuilder);
