   129→    private static void handleConnectorProxy(final ConfigurationModel connector,
   130→                                             final OkHttpClient.Builder okHttpBuilder) {
   131→        //if the connector has a proxy set
   132→        if (connector.getConnectorProxy() != null) {
   133→            //if there is any proxy in the proxylist
   134→            final var proxyConfiguration = connector
   135→                    .getConnectorProxy().stream().findAny().orElse(null);
   136→
   137→            if (proxyConfiguration != null) {
   138→                if (log.isDebugEnabled()) {
   139→                    log.debug("Proxy is set active! Configuring Proxy. [code=(IMSCOD0068)]");
   140→                }
