   142→                //create and set Proxy Authenticator with BasicAuth if
   143→                //proxy username and password are set
   144→                setProxyAuthenticator(okHttpBuilder, proxyConfiguration);
   145→
   146→                //create a custom proxySelector (will select the proxy when
   147→                //request goes to host not in NO_PROXY list, and NO_PROXY otherwise)
   148→                if (log.isDebugEnabled()) {
   149→                    log.debug("Creating a ProxySelector. [code=(IMSCOD0069)]");
   150→                }
   151→                setProxySelector(okHttpBuilder, proxyConfiguration);
   152→            }
   153→        }
