   156→    /**
   157→     * Select the Proxy being used.
   158→     *
   159→     * @param okHttpBuilder The Builder of the okHttp Client used for sending messages.
   160→     * @param proxyConfiguration The configuration of the proxy to be used.
   161→     */
   162→    private static void setProxySelector(final OkHttpClient.Builder okHttpBuilder,
   163→                                         final de.fraunhofer.iais.eis.Proxy proxyConfiguration) {
   164→        final var proxySelector = new ProxySelector() {
   165→            @Override
   166→            public List<Proxy> select(final URI uri) {
   167→
   168→                //create a List of size 1 containing the possible Proxy
   169→                final List<Proxy> proxyList = new ArrayList<>(1);
   170→
   171→                if (proxyConfiguration.getNoProxy().contains(uri)) {
   172→                    if (log.isDebugEnabled()) {
   173→                        log.debug("URI is in NoProxy List, no proxy is used. [code=(IMSCOD0070),"
   174→                                  + " uri=({})]", uri.toString());
   175→                    }
   176→
   177→                    //if the called uri is in the Exceptions of the
   178→                    //Connectors ProxyConfiguration use no proxy
   179→                    proxyList.add(Proxy.NO_PROXY);
   180→                } else {
   181→                    if (log.isDebugEnabled()) {
   182→                        log.debug("URI is not in NoProxy List, use configured Proxy."
   183→                                  + " [code=(IMSCOD0071), uri=({})]", uri.toString());
   184→                    }
   185→
   186→                    //else use proxy with ProxyConfig
   187→                    final var proxyAddress = proxyConfiguration.getProxyURI();
   188→                    final var proxyHost = proxyAddress.getHost();
   189→                    final int proxyPort = proxyAddress.getPort();
   190→
   191→                    if (log.isDebugEnabled()) {
   192→                        log.debug("Address: [code=(IMSCOD0072), host=({}), port=({})]",
   193→                                  proxyHost, proxyPort);
   194→                    }
   195→
   196→                    if (proxyHost == null || proxyHost.trim().equals("")) {
   197→                        if (log.isWarnEnabled()) {
   198→                            log.warn("Proxy hostname invalid! Trying to skip using this proxy!"
   199→                                     + " Please check configuration! [code=(IMSCOW0030),"
   200→                                     + " hostname=({})]", proxyHost);
   201→                        }
   202→                        proxyList.add(Proxy.NO_PROXY);
   203→                    } else if (proxyPort == -1) {
   204→                        if (log.isWarnEnabled()) {
   205→                            log.warn("Proxy port invalid! Trying to skip using this proxy!"
   206→                                     + " Please check configuration! [code=(IMSCOW0031),"
   207→                                     + " port=({})]", proxyPort);
   208→                        }
   209→                        proxyList.add(Proxy.NO_PROXY);
   210→                    } else {
   211→                        proxyList.add(new Proxy(Proxy.Type.HTTP,
   212→                                                new InetSocketAddress(proxyHost, proxyPort)));
   213→                    }
   214→
   215→                }
   216→                return proxyList;
   217→            }
