   251→                final var credential = Credentials.basic(proxyConfiguration
   252→                                                                 .getProxyAuthentication()
   253→                                                                 .getAuthUsername(),
   254→                                                         proxyConfiguration
   255→                                                                 .getProxyAuthentication()
   256→                                                                 .getAuthPassword());
