   478→    /**
   479→     * Adds an interceptor to handle Content-Encodings in response header.
   480→     */
   481→    private class EncodingInterceptor implements Interceptor {
   482→        @Override
   483→        @NotNull
   484→        public Response intercept(final Chain chain) throws IOException {
   485→            if (log.isDebugEnabled()) {
   486→                log.debug("EncodingInterceptor: Checking response encoding for gzip."
   487→                          + " [code=(IMSCOD0144)");
   488→            }
   489→
   490→            final var response = chain.proceed(chain.request());
   491→
   492→            return handleGzip(response);
   493→        }
   494→
   495→        private Response handleGzip(final Response response) {
   496→            final var bodyPresent = (response.body() != null);
   497→            final var gzipPresent = "gzip".equalsIgnoreCase(
   498→                    response.headers().get("Content-Encoding"));
   499→
   500→            if (!bodyPresent || !gzipPresent) {
   501→                if (log.isDebugEnabled()) {
   502→                    log.debug("EncodingInterceptor: No body in response or no gzip present."
   503→                              + " [code=(IMSCOD0145)");
   504→                }
   505→
   506→                return response;
   507→            } else {
   508→                if (log.isDebugEnabled()) {
   509→                    log.debug("EncodingInterceptor: Response body present and"
   510→                              + " gzip encoded, uncompressing. [code=(IMSCOD0146)");
   511→                }
   512→
   513→                try {
   514→                    final var responseBody = new GzipSource(response.body().source());
   515→                    final var contentLength = response.body().contentLength();
   516→                    final var strippedHeaders = response.headers()
   517→                                                        .newBuilder()
   518→                                                        .removeAll("Content-Encoding")
   519→                                                        .build();
   520→
   521→                    return response.newBuilder()
   522→                                   .headers(strippedHeaders)
   523→                                   .body(new RealResponseBody(
   524→                                           response.body().contentType().toString(),
   525→                                           contentLength,
   526→                                           Okio.buffer(responseBody)))
   527→                                   .build();
   528→                } catch (Exception e) {
   529→                    return response;
   530→                }
   531→            }
   532→        }
   533→    }
