                                   .headers(strippedHeaders)
                                   .body(new RealResponseBody(
                                           response.body().contentType().toString(),
                                           contentLength,
                                           Okio.buffer(responseBody)))
                                   .build();
                } catch (Exception e) {
                    return response;
                }
            }
