   219→            @Override
   220→            public void connectFailed(final URI uri,
   221→                                      final SocketAddress sa,
   222→                                      final IOException ioe) {
   223→                throw new UnsupportedOperationException(
   224→                        "The selected Proxy is unavailable!");
   225→            }
   226→        };
   227→
   228→        //set proxySelector for the okhttpclient
   229→        okHttpBuilder.proxySelector(proxySelector);
