   390→     * @param readTimeout Max timeout for waiting for the target response (null = default
   391→     *                    values are used).
   392→     * @param writeTimeout Max timeout for sending the response to the target (null = default
   393→     *                     values are used).
   394→     * @param callTimeout Max timeout for the whole http request (null = default values are used).
   395→     * @return An OkHttpClient configured using the current connector configuration and truststore
   396→     * certificates, with the given timeouts set.
   397→     */
   398→    public OkHttpClient getClientWithTimeouts(final Duration connectTimeout,
   399→                                              final Duration readTimeout,
   400→                                              final Duration writeTimeout,
   401→                                              final Duration callTimeout) {
   402→
   403→        final var withTimeout =
   404→                rebuildClientWithTimeouts(client, connectTimeout,
   405→                                          readTimeout, writeTimeout,
   406→                                          callTimeout);
   407→
   408→        if (log.isDebugEnabled()) {
   409→            log.debug("Ok Http Client Protocols: [code=(IMSCOD0076),"
   410→                      + " protocols=({})]", withTimeout.protocols());
