   415→    /**
   416→     * Set custom timeouts for the OkHttpClient and build one.
   417→     *
   418→     * @param client The client which is rebuilt with.
   419→     * @param connectTimeout Max timeout for connecting to target host (null = default values
   420→     *                       are used).
   421→     * @param readTimeout Max timeout for waiting for the target response (null = default
   422→     *                    values are used).
   423→     * @param writeTimeout Max timeout for sending the response to the target (null = default
   424→     *                     values are used).
   425→     * @param callTimeout Max timeout for the whole http request (null = default values are used).
   426→     * @return An OkHttpClient rebuilt with the given timeouts.
   427→     */
   428→    private OkHttpClient rebuildClientWithTimeouts(final OkHttpClient client,
   429→                                                   final Duration connectTimeout,
   430→                                                   final Duration readTimeout,
   431→                                                   final Duration writeTimeout,
   432→                                                   final Duration callTimeout) {
   433→        final var builder = client.newBuilder();
   434→
   435→        if (connectTimeout != null) {
   436→            if (log.isDebugEnabled()) {
   437→                log.debug("Setting connect timeout: [code=(IMSCOD0077),"
   438→                          + " timeout=({})]", connectTimeout.toString());
   439→            }
   440→            builder.connectTimeout(connectTimeout);
   441→        }
   442→        if (readTimeout != null) {
   443→            if (log.isDebugEnabled()) {
   444→                log.debug("Setting read timeout: [code=(IMSCOD0078), timeout=({})]",
   445→                          readTimeout.toString());
   446→            }
   447→            builder.readTimeout(readTimeout);
   448→        }
   449→        if (writeTimeout != null) {
   450→            if (log.isDebugEnabled()) {
   451→                log.debug("Setting write timeout: [code=(IMSCOD0079), timeout=({})]",
   452→                          writeTimeout.toString());
   453→            }
   454→            builder.writeTimeout(writeTimeout);
   455→        }
   456→        if (callTimeout != null) {
   457→            if (log.isDebugEnabled()) {
   458→                log.debug("Setting call timeout. [code=(IMSCOD0080), timeout=({})]",
   459→                          callTimeout.toString());
   460→            }
   461→            builder.callTimeout(callTimeout);
   462→        }
   463→
   464→        if (log.isDebugEnabled()) {
   465→            log.debug("Building client. [code=(IMSCOD0081)]");
   466→        }
   467→
   468→        final var okHttpClient = builder.build();
   469→
   470→        if (log.isDebugEnabled()) {
   471→            log.debug("Ok Http Client Protocols [code=(IMSCOD0082),"
   472→                      + " protocols=({})]", okHttpClient.protocols());
   473→        }
