   152→    private void setClientCertificate(final JSONObject responseJson)
   153→            throws CertificateException {
   154→        final var responseCert = responseJson.getJSONObject("cert");
   155→        final var responseData = responseCert.getJSONArray("data");
   156→        var bytes = new byte[responseData.length()];
   157→
   158→        for (var i = 0; i < responseData.length(); i++) {
   159→            bytes[i] = (byte) (((int) responseData.get(i)) & BYTESINT);
   160→        }
