   219→     * cannot be created
   220→     * @throws IOException when the Extensions cannot be added to the CSR
   221→     */
   222→    private PKCS10CertificationRequest createCSR()
   223→            throws IOException, OperatorCreationException {
   224→        //create csr builder with principal
   225→        final var p10Builder = new JcaPKCS10CertificationRequestBuilder(
   226→                new X500Principal("C=DE, ST=Bonn, L=NRW, O=truzzt, CN=*.truzzt.org"),
   227→                         generatedKeyPair.getPublic());
   228→
   229→        //add extensions
   230→        final var extensionsGenerator = new ExtensionsGenerator();
   231→
   232→        //basic constraints = false
   233→        extensionsGenerator.addExtension(Extension.basicConstraints, false,
   234→                                         new BasicConstraints(false));
   235→
   236→        //add subject alternative names
   237→        final var sans = new ASN1Encodable[]{
   238→                new GeneralName(GeneralName.dNSName, "*.truzzt.org"),
   239→                new GeneralName(GeneralName.dNSName, "*.truzzt.com")
   240→        };
   241→
   242→        final var sansExtension = new DERSequence(sans);
   243→        extensionsGenerator
   244→                .addExtension(Extension.subjectAlternativeName,
   245→                              false,
   246→                              sansExtension);
   247→
   248→        //TODO add SKI extension but currently working without it)
   249→        //extensionsGenerator.addExtension(Extension.subjectKeyIdentifier,
   250→        // true, new SubjectKeyIdentifier());
   251→
   252→        final var extensions = extensionsGenerator.generate();
   253→        p10Builder.addAttribute(
   254→                PKCSObjectIdentifiers.pkcs_9_at_extensionRequest,
   255→                extensions);
   256→
   257→        //create csBuilder for signing the request
   258→        final var csBuilder = new JcaContentSignerBuilder("SHA256withRSA");
   259→        final var signer = csBuilder.build(generatedKeyPair.getPrivate());
   260→
   261→        //build and return the csr
   262→        return p10Builder.build(signer);
   263→    }
   264→
   265→    /**
   266→     * Get the DAT Token from Orbiter DAPS.
   267→     *
   268→     * @param dapsUrl The URL of the DAPS
   269→     * @return access jwt token as String
   270→     */
   271→    @Override
   272→    public String acquireToken(final String dapsUrl) {
   273→        final var client = clientProvider.getClient();
   274→
   275→        //register at Orbiter DAPS if this is called the first time
   276→        if (id == null || generatedKeyPair == null || clientCert == null) {
   277→            //does this have to happen in the framework or should we expect
   278→            // a keystore provided by the user (like Aisec Daps Client)
   279→            createClient();
   280→        }
   281→
   282→        final var token = getRequestToken();
   283→        final var formBody = getRequestBody(token);
   284→        final var request = getRequestMessage(dapsUrl, formBody);
   285→
   286→        try {
   287→            return getDAT(client, request);
   288→        } catch (IOException e) {
   289→            if (log.isWarnEnabled()) {
   290→                log.warn("[code=(IMSCOW0029)] " + e.getMessage(), e);
   291→            }
   292→
   293→            return "";
   294→        }
   295→    }
   296→
   297→    private String getDAT(
   298→            final OkHttpClient client,
   299→            final Request request)
   300→            throws IOException {
   301→        final var jwtResponse = client.newCall(request).execute();
   302→        final var responseJson = new JSONObject(
   303→                Objects.requireNonNull(jwtResponse.body()).string());
   304→
   305→        return responseJson.getString("accessToken");
   306→    }
   307→
   308→    private Request getRequestMessage(final String dapsUrl,
   309→                                      final RequestBody formBody) {
   310→        return new Request.Builder()
   311→                .url(dapsUrl)
   312→                .post(formBody)
   313→                .build();
   314→    }
   315→
   316→    private RequestBody getRequestBody(final String token) {
   317→        return new FormBody.Builder()
   318→                .add("grant_type", "client_assertion_type")
   319→                .add("client_assertion_type",
   320→                     "urn:ietf:params:oauth:client-assertion-type:jwt-bearer")
   321→                .add("client_assertion", token)
   322→                .add("scope", "idsc:IDS_CONNECTOR_ATTRIBUTES_ALL")
   323→                .add("client_id", id)
   324→                .build();
   325→    }
   326→
   327→    private String getRequestToken() {
   328→        final var jwtb =
   329→                Jwts.builder()
   330→                    .setIssuer("localhost")
   331→                    .setSubject(id)
   332→                    .claim("@context",
   333→                           "https://w3id.org/idsa/contexts/context.jsonld")
   334→                    .claim("@type", "ids:DatRequestToken")
   335→                    .setExpiration(
   336→                            Date.from(Instant.now().plus(Duration.ofDays(1))))
   337→                    .setAudience("all")
   338→                    .setIssuedAt(Date.from(
   339→                            Instant.now().minusSeconds(SECONDS_TO_SUBTRACT)))
   340→                    .setNotBefore(Date.from(
   341→                            Instant.now().minusSeconds(SECONDS_TO_SUBTRACT)));
   342→
   343→        return jwtb.signWith(SignatureAlgorithm.RS256,
   344→                             generatedKeyPair.getPrivate()).compact();
   345→    }
