    20→package ids.messaging.protocol.multipart.parser;
    21→
    22→import java.io.ByteArrayInputStream;
    23→import java.io.InputStream;
    24→import java.util.Map;
    25→import java.util.concurrent.ConcurrentHashMap;
    26→
    27→import lombok.Getter;
    28→import org.apache.commons.fileupload.FileUpload;
    29→import org.apache.commons.fileupload.FileUploadException;
    30→import org.apache.commons.fileupload.UploadContext;
    31→import org.apache.commons.fileupload.disk.DiskFileItemFactory;
    32→
    33→/**
    34→ * Utility Class for parsing Multipart Maps from String responses.
    35→ */
    36→public final class MultipartParser implements UploadContext {
    37→
    38→    /**
    39→     * The multipart body as string.
    40→     */
    41→    private String postBody;
    42→
    43→    /**
    44→     * Boundary of the received message.
    45→     */
    46→    private String boundary;
    47→
    48→    /**
    49→     * Parameters used to parse the response to a Map-Object.
    50→     */
    51→    @Getter
    52→    private Map<String, String> parameters = new ConcurrentHashMap<>();
    53→
    54→    /**
    55→     * Constructor for the MultipartStringParser used internally
    56→     * to parse a multipart response to a Map<Partname, MessagePart>.
    57→     *
    58→     * @param postBody A multipart response body as string.
    59→     * @throws FileUploadException If there are problems reading/parsing the postBody.
    60→     */
    61→    private MultipartParser(final String postBody)
    62→            throws FileUploadException, MultipartParseException {
    63→        this.postBody = postBody;
    64→
    65→        if (postBody.length() <= 2 || postBody.indexOf('\n') <= 2)  {
    66→            throw new MultipartParseException(
    67→                    "String could not be parsed, could not find a boundary!");
    68→        }
    69→
    70→        this.boundary = postBody.substring(2, postBody.indexOf('\n')).trim();
    71→
    72→        final var upload = new FileUpload(new DiskFileItemFactory());
    73→        final var fileItems = upload.parseRequest(this);
    74→
    75→        for (final var fileItem : fileItems) {
    76→            if (fileItem.isFormField()) {
    77→                //put the parameters into the map as "name, content"
    78→                parameters.put(fileItem.getFieldName(), fileItem.getString());
    79→            }
    80→        }
    81→    }
    82→
    83→    /**
    84→     * Convert a String from a multipart response to a Map with Partname/MessagePart.
    85→     *
    86→     * @param postBody A multipart response body as string.
    87→     * @return A Map from partname on content.
    88→     * @throws MultipartParseException If there are problems reading/parsing the postBody.
    89→     */
    90→    public static Map<String, String> stringToMultipart(final String postBody)
    91→            throws MultipartParseException {
    92→        try {
    93→            final var resultMap = new MultipartParser(postBody).getParameters();
    94→
    95→            if (resultMap.keySet().isEmpty()) {
    96→                throw new MultipartParseException(
    97→                        "Could not parse Multipart! No parts found!");
    98→            }
    99→
   100→            return resultMap;
   101→        } catch (FileUploadException e) {
   102→            throw new MultipartParseException(
   103→                    "Could not parse given String:\n" + postBody, e);
   104→        }
   105→    }
   106→
   107→    //these methods must be implemented because of the UploadContext interface
   108→    @Override
   109→    public long contentLength() {
   110→        return postBody.length();
   111→    }
   112→
   113→    @Override
   114→    public String getCharacterEncoding() {
   115→        return "Cp1252";
   116→    }
   117→
   118→    @Override
   119→    public String getContentType() {
   120→        return "multipart/form-data, boundary=" + this.boundary;
   121→    }
   122→
   123→    @Override
   124→    public int getContentLength() {
   125→        return -1;
   126→    }
   127→
   128→    @Override
   129→    public InputStream getInputStream() {
   130→        return new ByteArrayInputStream(postBody.getBytes());
   131→    }
   132→}
